import{_ as i,o as t,c as a,a2 as s}from"./chunks/framework.D9E58p8B.js";const m=JSON.parse('{"title":"AI clients","description":"","frontmatter":{"title":"AI clients"},"headers":[],"relativePath":"en/guide/clients-mcp.md","filePath":"en/guide/clients-mcp.md"}'),n={name:"en/guide/clients-mcp.md"};function o(r,e,l,h,d,p){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="registering-daimon-in-your-ai-clients" tabindex="-1">Registering Daimon in your AI clients <a class="header-anchor" href="#registering-daimon-in-your-ai-clients" aria-label="Permalink to &quot;Registering Daimon in your AI clients&quot;">​</a></h1><p>Daimon registers itself as an MCP server named <code>daimon</code> in the clients it detects on your computer. Your client then launches it over stdio, with the <code>serve</code> argument.</p><h2 id="three-ways-to-register-it" tabindex="-1">Three ways to register it <a class="header-anchor" href="#three-ways-to-register-it" aria-label="Permalink to &quot;Three ways to register it&quot;">​</a></h2><ol><li><strong>The setup walkthrough</strong> (panel › <strong>Relancer l&#39;installation…</strong> (Re-run setup…)).</li><li><strong>The panel</strong>, with one switch per client.</li><li><strong>A terminal.</strong></li></ol><h3 id="from-a-terminal" tabindex="-1">From a terminal <a class="header-anchor" href="#from-a-terminal" aria-label="Permalink to &quot;From a terminal&quot;">​</a></h3><p>macOS:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/Applications/Daimon.app/Contents/MacOS/Daimon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # what is detected, what is registered</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/Applications/Daimon.app/Contents/MacOS/Daimon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # register in every detected client</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/Applications/Daimon.app/Contents/MacOS/Daimon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # remove itself</span></span></code></pre></div><p>Windows (PowerShell): pipe the output to <code>Out-Host</code> so the prompt waits for the answer.</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LOCALAPPDATA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\\Daimon\\Daimon.exe&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> status </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Out-Host</span></span></code></pre></div><p>After registering, <strong>restart your AI client</strong>.</p><h2 id="known-clients" tabindex="-1">Known clients <a class="header-anchor" href="#known-clients" aria-label="Permalink to &quot;Known clients&quot;">​</a></h2><p>Daimon knows the configuration of: Claude Code, Claude Desktop, Codex, Gemini CLI, Antigravity, Cursor (editor and CLI), Windsurf, VS Code with Copilot, GitHub Copilot CLI, Zed, JetBrains Junie, Cline, Roo Code, Continue, Amazon Q Developer CLI, opencode, Crush, Mistral Vibe, Qwen Code, Droid, Grok CLI, Goose, LM Studio, 5ire, Witsy, AnythingLLM Desktop, OpenDesign and Trae.</p><p>Not all of them have been proven end to end. If one misbehaves, <a href="https://github.com/ArboRithm/Daimon/issues" target="_blank" rel="noreferrer">open an issue</a>.</p><h2 id="another-mcp-client" tabindex="-1">Another MCP client <a class="header-anchor" href="#another-mcp-client" aria-label="Permalink to &quot;Another MCP client&quot;">​</a></h2><p>Declare a <strong>stdio</strong> server whose command is:</p><table tabindex="0"><thead><tr><th>Platform</th><th>Command</th><th>Argument</th></tr></thead><tbody><tr><td>macOS</td><td><code>/Applications/Daimon.app/Contents/MacOS/Daimon</code></td><td><code>serve</code></td></tr><tr><td>Windows</td><td><code>%LOCALAPPDATA%\\Daimon\\Daimon.exe</code></td><td><code>serve</code></td></tr></tbody></table><p>The only argument is <code>serve</code>. The server name Daimon itself uses is <code>daimon</code>.</p><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Verify&quot;">​</a></h2><p>Ask your AI to call <a href="/Daimon/en/reference/diagnostic.html#daimon-doctor"><code>daimon_doctor</code></a>, then <a href="/Daimon/en/reference/diagnostic.html#main-ceiling"><code>main_ceiling</code></a> to learn the active ceiling.</p>`,19)])])}const g=i(n,[["render",o]]);export{m as __pageData,g as default};
